// Rebuild exactly what OpsCore signed: "<timestamp>.<raw body bytes>" (OpsCore DECISIONS D26).
// The raw body comes from the Wait node's rawBody option, so JSON parsing can't reorder keys.
const meta = $('SHA-256 of file').first().json;          // intake metadata + file_sha256
const job = $('Submit to OpsCore').first().json;         // { job_id, status: "queued" }
const item = $input.first();
const headers = item.json.headers || {};
const base = { ...meta, job_id: job.job_id };
if (!headers['x-opscore-signature'] || !item.binary?.data) {
  // The Wait node timed out: no callback arrived.
  return [{ json: { ...base, timed_out: true, to_sign: '', signature: '', age_s: 0, result: null } }];
}
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const timestamp = Number(headers['x-opscore-timestamp']);
return [{
  json: {
    ...base,
    timed_out: false,
    to_sign: `${headers['x-opscore-timestamp']}.${raw}`,
    signature: headers['x-opscore-signature'],
    age_s: Math.round(Date.now() / 1000 - timestamp),
    result: JSON.parse(raw),
  },
}];

const v = $('HMAC-SHA256').first().json;     // verified callback + intake metadata
const ledger = $input.first().json;
const r = v.result;
const d = r.data;
const confidence = r.confidence?.overall ?? 0;

let route;
if (r.status === 'failed' || !d) route = 'failed';
else if (r.duplicate_of || ledger.ledger_duplicate_of) route = 'duplicate';
else if (r.status === 'done') route = 'auto_approve';      // OpsCore: validation clean and confidence >= 0.85
else route = 'needs_review';

// Anomaly flags are informational: they appear in Slack and the sheet but never block an invoice.
const anomalies = [];
if (d) {
  const n = Number(ledger.vendor_invoice_count || 0);
  const avg = Number(ledger.vendor_avg_total || 0);
  if (n === 0) anomalies.push('new vendor (no earlier invoices in the ledger)');
  else if (avg > 0 && d.total >= 3 * avg) anomalies.push(`total is ${(d.total / avg).toFixed(1)}x this vendor's average of ${avg.toFixed(2)} ${d.currency}`);
  if (d.due_date && d.due_date < d.invoice_date) anomalies.push('due date is before the invoice date');
  if (d.invoice_date > $now.toISODate()) anomalies.push(`invoice date is in the future (${d.invoice_date})`);
}
const issues = (r.validation?.errors || []).map(e => `${e.field}: ${e.message}`);

return [{
  json: {
    ...v, route, confidence, anomalies, issues,
    invoice: d,
    duplicate_of: r.duplicate_of || ledger.ledger_duplicate_of || null,
    duplicate_source: r.duplicate_of ? 'OpsCore' : (ledger.ledger_duplicate_of ? 'ledger' : null),
  },
}];

