const v = $('Decide route').first().json;
const form = $json.data || $json;                 // the Slack form answers, keyed by field label
const decision = String(form['Decision'] || '');
const invoice = { ...v.invoice };
const edits = {};
if (decision === 'Approve with corrections') {
  const t = form['Corrected total'];
  if (t !== undefined && t !== null && String(t).trim() !== '' && Number(t) !== invoice.total) {
    edits.total = { from: invoice.total, to: Number(t) };
    invoice.total = Number(t);
  }
  const no = String(form['Corrected invoice number'] || '').trim();
  if (no && no !== invoice.invoice_no) {
    edits.invoice_no = { from: invoice.invoice_no, to: no };
    invoice.invoice_no = no;
  }
}
const approved = decision.startsWith('Approve');
return [{
  json: {
    ...v, invoice, edits,
    decision: decision || 'no answer within 24 h',
    review_note: String(form['Note'] || ''),
    status: !approved ? 'rejected' : (Object.keys(edits).length ? 'approved_with_edits' : 'approved'),
    approved_by: approved ? 'Slack #finance-approvals' : null,
  },
}];

const j = $json;
const inv = j.invoice;
const lines = inv.line_items || [];
const search_text = [
  `Invoice ${inv.invoice_no} from ${inv.vendor}.`,
  `Invoice date ${inv.invoice_date}${inv.due_date ? `, due ${inv.due_date}` : ''}.`,
  `Currency ${inv.currency}. Subtotal ${inv.subtotal.toFixed(2)}, tax ${inv.tax.toFixed(2)}, total ${inv.total.toFixed(2)}.`,
  `Status ${j.status}.`,
  lines.length ? 'Line items: ' + lines.map((l, i) => `${i + 1}) ${l.description}: ${l.qty} x ${l.unit_price} = ${l.amount}`).join('; ') + '.' : '',
].filter(Boolean).join(' ');
return [{
  json: {
    ...j,
    search_text,
    record: {
      job_id: j.job_id, ...inv, status: j.status, confidence: j.confidence, approved_by: j.approved_by,
      source: j.source, source_email: j.source_email || null, file_sha256: j.file_sha256, file_name: j.file_name,
      anomalies: j.anomalies, edits: j.edits || {},
    },
  },
}];

const j = $('Ledger record').first().json;
const inv = j.invoice;
return [{
  json: {
    'Received at': DateTime.fromISO(j.received_at).toFormat('yyyy-LL-dd HH:mm'),
    'Invoice no': inv.invoice_no,
    'Vendor': inv.vendor,
    'Invoice date': inv.invoice_date,
    'Due date': inv.due_date || '',
    'Currency': inv.currency,
    'Subtotal': inv.subtotal,
    'Tax': inv.tax,
    'Total': inv.total,
    'Status': j.status,
    'Confidence': j.confidence,
    'Approved by': j.approved_by,
    'Source': j.source,
    'Anomalies': j.anomalies.join('; '),
    'OpsCore job': j.job_id,
  },
}];

const j = $json;
let outcome, detail;
if (j.route === undefined) {
  outcome = 'failed';
  detail = j.timed_out
    ? `No callback from OpsCore within 20 minutes (job ${j.job_id})`
    : `Rejected an untrusted OpsCore callback for job ${j.job_id}: ${('sha256=' + j.computed) !== j.signature ? 'signature mismatch' : `stale timestamp (${j.age_s} s old)`}`;
} else if (j.route === 'duplicate') {
  outcome = 'duplicate';
  detail = `Duplicate of ${j.duplicate_of} (found by ${j.duplicate_source}): ${j.invoice.invoice_no} from ${j.invoice.vendor}, ${j.invoice.currency} ${j.invoice.total.toFixed(2)}`;
} else if (j.status === 'rejected') {
  outcome = 'rejected';
  detail = `Rejected in Slack review (${j.decision})${j.review_note ? ': ' + j.review_note : ''}`;
} else {
  outcome = 'failed';
  detail = `OpsCore could not extract ${j.file_name}: ${(j.issues || []).join('; ') || 'no detail'}`;
}
return [{
  json: {
    outcome, detail, job_id: j.job_id, file_sha256: j.file_sha256, file_name: j.file_name, source: j.source,
    duplicate_of: j.duplicate_of || null, invoice_no: j.invoice?.invoice_no || null, vendor: j.invoice?.vendor || null,
    received_at: j.received_at,
  },
}];

const j = $('Describe exception').first().json;
return [{
  json: {
    'Received at': DateTime.fromISO(j.received_at).toFormat('yyyy-LL-dd HH:mm'),
    'File': j.file_name,
    'Outcome': j.outcome,
    'Detail': j.detail,
    'Duplicate of': j.duplicate_of || '',
    'OpsCore job': j.job_id,
    'Source': j.source,
  },
}];
